    scanAndStart();
  });
  if (document.body){
    mo.observe(document.body, { childList: true, subtree: true });
  } else {
    document.addEventListener("DOMContentLoaded", function(){
      mo.observe(document.body, { childList: true, subtree: true });
      scanAndStart();
    });
  }
})();
